export const RENEWAL_ABILITY_SLOTS={"116":{"primary":"Countercurrent","secondary":"Battle Readiness","hidden":"Battle Rush"},"118":{"primary":"Dread Presence","secondary":"Stoneplate","hidden":"Firm Stance"},"059":{"primary":"Dread Presence","secondary":"Ambush","hidden":"Battle Readiness"}};

export const RENEWAL_ART_IDS=['057','058','059','116','117','118','504'];
export function installEvolutionRenewal(data){if(data.evolutionRenewalVersion)return;data.evolutionRenewalVersion=1;
 for(const patch of RENEWAL_SPECIES){const s=data.species.find(s=>s.id===patch.id);Object.assign(s,patch);}
 data.species.push({...VIGORFUME,abilities:{},growth_balance_version:1});
 for(const [id,slots] of Object.entries(RENEWAL_ABILITY_SLOTS))data.species.find(s=>s.id===id).ability_names={...slots};
 for(const s of data.species.filter(s=>RENEWAL_ART_IDS.includes(s.id))){s.abilities=Object.fromEntries(Object.entries(s.ability_names).map(([slot,name])=>[slot,'ABILITY_'+name.toUpperCase().replace(/[^A-Z0-9]+/g,'_')]));s.companion_motion='walk';}
 for(const m of data.moves)if(RENEWAL_MOVE_PATCHES[m.id])Object.assign(m,RENEWAL_MOVE_PATCHES[m.id]);
 for(const m of RENEWAL_MOVES){if(data.moves.some(x=>x.id===m.id))throw Error('Renewal move collision '+m.id);data.moves.push({...m});}
 data.learnsets=data.learnsets.filter(l=>!RENEWAL_LEARNSETS[l.species_id]);
 for(const [id,rows]of Object.entries(RENEWAL_LEARNSETS))for(const [level,move_id]of rows)data.learnsets.push({species_id:id,move_id,name:data.moves.find(m=>m.id===move_id).name,level,method:'LEVEL_UP',evolutionRenewal:true});
}
